// Keeps the latest import rate schedule (applicable_rates) for the planner, and says
// when the planned window starts.
// The node resends its output when the current half-hour rate changes, so this runs
// at each half-hour boundary as well as after each poll.
const p = msg.payload;
if (!p || typeof p !== 'object') return null;
if (Array.isArray(p.applicable_rates) && p.applicable_rates.length > 0) {
    flow.set('latestImportRates', p.applicable_rates);
}

const plan = flow.get('plannedWindow');
if (!plan || plan.announced) return null;
const now = Date.now();
const start = Date.parse(plan.start);
const end = Date.parse(plan.end);
if (now < start) return null;
plan.announced = true;
flow.set('plannedWindow', plan);
if (now >= end) return null; // missed it (for example Node-RED was down)
return { topic: 'Cheapest window started', payload: plan };

// Finds the cheapest run of back-to-back half hours in the import schedule
// (applicable_rates) that finishes by your deadline.
//
// ===== EDIT THESE =====
const RUN_MINUTES = 120;          // how long the appliance needs, in minutes
const FINISH_BY = '07:00';        // latest finish, HH:MM on the hour or half hour. null = any time in the schedule
const TIME_ZONE = 'Europe/London'; // used for FINISH_BY and for the times in the message
// ======================

const slots = flow.get('latestImportRates') || [];
const now = Date.now();
const fmt = (ms) => new Date(ms).toLocaleTimeString('en-GB', { timeZone: TIME_ZONE, hour: '2-digit', minute: '2-digit' });

// Future slots only, in time order, with a price.
const future = slots
    .map((s) => ({ from: Date.parse(s.valid_from), to: Date.parse(s.valid_to), p: s.value_pence_per_kwh }))
    .filter((s) => Number.isFinite(s.from) && Number.isFinite(s.to) && typeof s.p === 'number' && s.from >= now)
    .sort((a, b) => a.from - b.from);

// Stop at the first slot that ends at FINISH_BY (in TIME_ZONE).
let usable = future;
if (FINISH_BY) {
    const cut = future.findIndex((s) => fmt(s.to) === FINISH_BY);
    if (cut !== -1) usable = future.slice(0, cut + 1);
}

const need = Math.ceil(RUN_MINUTES / 30);
let best = null;
for (let i = 0; i + need <= usable.length; i++) {
    const run = usable.slice(i, i + need);
    // Back-to-back only: each slot must start where the last one ended.
    if (run.some((s, j) => j > 0 && s.from !== run[j - 1].to)) continue;
    const avg = run.reduce((sum, s) => sum + s.p, 0) / need;
    if (!best || avg < best.avg) best = { start: run[0].from, end: run[need - 1].to, avg };
}

if (!best) {
    flow.set('plannedWindow', null);
    node.status({ fill: 'yellow', shape: 'ring', text: 'no window found' });
    return { topic: 'No cheapest window', payload: `No ${RUN_MINUTES}-minute window found${FINISH_BY ? ` before ${FINISH_BY}` : ''}. The node may not have read the rate schedule yet.` };
}

const plan = {
    start: new Date(best.start).toISOString(),
    end: new Date(best.end).toISOString(),
    avg_pence: Math.round(best.avg * 100) / 100,
    text: `Cheapest ${RUN_MINUTES} minutes: ${fmt(best.start)} to ${fmt(best.end)}, average ${best.avg.toFixed(2)} p/kWh.`,
    announced: false,
};
flow.set('plannedWindow', plan);
node.status({ fill: 'green', shape: 'dot', text: `${fmt(best.start)} to ${fmt(best.end)}` });
return { topic: 'Cheapest window planned', payload: plan };
